package com.greenocean.backend.trust;

import com.greenocean.backend.common.exception.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.support.TransactionTemplate;import org.springframework.scheduling.annotation.Scheduled;
import java.time.*;import java.util.*;

@Service
public class OperationsAlerts {
 private final java.util.concurrent.atomic.AtomicBoolean dispatching=new java.util.concurrent.atomic.AtomicBoolean();
 private final java.util.concurrent.ThreadPoolExecutor dispatch=new java.util.concurrent.ThreadPoolExecutor(1,1,0,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.SynchronousQueue<>(),Thread.ofPlatform().daemon(true).name("operation-alert-dispatch").factory(),new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
 private final JdbcTemplate db;private final IncidentOperations operations;private final TrustAuthority authority;private final OperationsAlertGateway gateway;private final TransactionTemplate tx;private final tools.jackson.databind.ObjectMapper json;private final boolean enabled;private final int escalationSeconds;
 public OperationsAlerts(JdbcTemplate db,IncidentOperations operations,TrustAuthority authority,OperationsAlertGateway gateway,org.springframework.transaction.PlatformTransactionManager manager,tools.jackson.databind.ObjectMapper json,@Value("${greenocean.operations.alert-worker-enabled:false}")boolean enabled,@Value("${greenocean.operations.alert-escalation-seconds:300}")int escalationSeconds){this.db=db;this.operations=operations;this.authority=authority;this.gateway=gateway;this.tx=new TransactionTemplate(manager);this.json=json;this.enabled=enabled;if(escalationSeconds<30||escalationSeconds>3600)throw new IllegalArgumentException("Choose an alert escalation interval of30–3600 seconds");this.escalationSeconds=escalationSeconds;}
 @Transactional public UUID route(UUID who,UUID sid,String domain,UUID recipient,String destination,int level,Instant expires){operations.require(who,sid,domain);if(!authority.has(who,"TRUST_PLATFORM")||!authority.has(recipient,TrustAuthority.role(domain)))throw new ForbiddenException("Explicit current staffing and recipient purpose authority required");if(!Set.of("PRIMARY","ESCALATION").contains(destination)||level<0||level>1||expires==null||!expires.isAfter(Instant.now())||expires.isAfter(Instant.now().plusSeconds(30*86400)))throw new IllegalArgumentException("Choose a bounded current alert route");authority.budget(who,"ALERT_ROUTE_CREATED",20);UUID id=UUID.randomUUID();db.update("INSERT INTO operation_alert_routes(id,domain,recipient_id,destination_key,escalation_level,author_id,author_session,author_version,expires_at) VALUES(?,?,?,?,?,?,?,?,?)",id,domain,recipient,destination,level,who,sid,operations.version(who,sid),expires.atOffset(ZoneOffset.UTC));return id;}
 @Transactional public void approve(UUID who,UUID sid,UUID id){var rows=db.queryForList("SELECT domain,author_id FROM operation_alert_routes WHERE id=?",id);if(rows.isEmpty())throw new NotFoundException("Route unavailable");db.queryForList("SELECT id FROM users WHERE id=? FOR SHARE",rows.getFirst().get("author_id"));String domain=(String)rows.getFirst().get("domain");operations.require(who,sid,domain);if(!authority.has(who,"TRUST_PLATFORM"))throw new ForbiddenException("Current explicit staffing authority required");var r=db.queryForMap("SELECT *,expires_at>CURRENT_TIMESTAMP AS live FROM operation_alert_routes WHERE id=? FOR UPDATE",id);if(who.equals(r.get("author_id")))throw new ForbiddenException("A second operator must independently approve the route");if(r.get("approved_by")!=null||r.get("revoked_at")!=null||!Boolean.TRUE.equals(r.get("live")))throw new ConflictException("A current unapproved route is required");UUID author=(UUID)r.get("author_id"),authorSid=(UUID)r.get("author_session");operations.require(author,authorSid,domain);if(!authority.has(author,"TRUST_PLATFORM")||!Objects.equals(r.get("author_version"),operations.version(author,authorSid)))throw new ConflictException("Route author authority or session changed");db.update("UPDATE operation_alert_routes SET approved_by=? WHERE id=?",who,id);authority.audit(who,id,"ALERT_ROUTE_APPROVED");}
 @Transactional public void acknowledgeRoute(UUID who,UUID sid,UUID id){var hint=db.queryForList("SELECT domain FROM operation_alert_routes WHERE id=? AND recipient_id=?",id,who);if(hint.isEmpty())throw new NotFoundException("Current assigned route required");operations.require(who,sid,(String)hint.getFirst().get("domain"));var rows=db.queryForList("SELECT domain FROM operation_alert_routes WHERE id=? AND recipient_id=? AND approved_by IS NOT NULL AND revoked_at IS NULL AND expires_at>CURRENT_TIMESTAMP FOR UPDATE",id,who);if(rows.isEmpty())throw new NotFoundException("Current assigned alert route required");operations.require(who,sid,(String)rows.getFirst().get("domain"));db.update("UPDATE operation_alert_routes SET acknowledged_at=CURRENT_TIMESTAMP WHERE id=?",id);authority.audit(who,id,"ALERT_ROUTE_RECIPIENT_ACKNOWLEDGED");}
 @Transactional public void revoke(UUID who,UUID sid,UUID id){var hint=db.queryForList("SELECT domain FROM operation_alert_routes WHERE id=?",id);if(hint.isEmpty())throw new NotFoundException("Route unavailable");operations.require(who,sid,(String)hint.getFirst().get("domain"));var rows=db.queryForList("SELECT domain,recipient_id FROM operation_alert_routes WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw new NotFoundException("Route unavailable");operations.require(who,sid,(String)rows.getFirst().get("domain"));if(!who.equals(rows.getFirst().get("recipient_id"))&&!authority.has(who,"TRUST_PLATFORM"))throw new ForbiddenException("Own route or current staffing authority required");db.update("UPDATE operation_alert_routes SET revoked_at=COALESCE(revoked_at,CURRENT_TIMESTAMP) WHERE id=?",id);db.update("UPDATE operation_alerts SET state='CANCELLED',claim_id=NULL WHERE route_id=? AND state IN('QUEUED','CLAIMED')",id);authority.audit(who,id,"ALERT_ROUTE_REVOKED");}
 @Transactional public void acknowledge(UUID who,UUID sid,UUID id){var hint=db.queryForList("SELECT r.domain,r.id AS route_id FROM operation_alerts a JOIN operation_alert_routes r ON r.id=a.route_id WHERE a.id=?",id);if(hint.isEmpty())throw new NotFoundException("Alert unavailable");operations.require(who,sid,(String)hint.getFirst().get("domain"));db.queryForList("SELECT id FROM operation_alert_routes WHERE id=? FOR UPDATE",hint.getFirst().get("route_id"));var rows=db.queryForList("SELECT r.domain,r.recipient_id,a.state,r.revoked_at,r.expires_at>CURRENT_TIMESTAMP AS live FROM operation_alerts a JOIN operation_alert_routes r ON r.id=a.route_id WHERE a.id=? FOR UPDATE OF a,r",id);if(rows.isEmpty())throw new NotFoundException("Alert unavailable");var r=rows.getFirst();operations.require(who,sid,(String)r.get("domain"));if(!who.equals(r.get("recipient_id")))throw new ForbiddenException("Only the current recipient may acknowledge actual receipt");if(!"DELIVERED".equals(r.get("state"))||r.get("revoked_at")!=null||!Boolean.TRUE.equals(r.get("live")))throw new ConflictException("Successful transport delivery and a current route are required before human acknowledgement");db.update("UPDATE operation_alerts SET state='ACKNOWLEDGED',acknowledged_at=CURRENT_TIMESTAMP,acknowledged_by=? WHERE id=?",who,id);authority.audit(who,id,"ALERT_HUMAN_ACKNOWLEDGED");}
 @Transactional public List<Map<String,Object>> routes(UUID who,UUID sid,String domain){operations.require(who,sid,domain);var rows=db.queryForList("SELECT id,recipient_id,destination_key,escalation_level,author_id,approved_by,acknowledged_at,expires_at,revoked_at FROM operation_alert_routes WHERE domain=? ORDER BY created_at DESC LIMIT 50",domain);for(var r:rows)r.put("transport_configured",gateway.configured((String)r.get("destination_key")));return rows;}
 @Transactional public List<Map<String,Object>> deliveries(UUID who,UUID sid,String domain){operations.require(who,sid,domain);return db.queryForList("SELECT a.id,a.incident_id,a.state,a.attempts,a.next_attempt_at,a.delivered_at,a.acknowledged_at,a.last_status,r.recipient_id=? AS own_alert FROM operation_alerts a JOIN operation_alert_routes r ON r.id=a.route_id WHERE r.domain=? ORDER BY a.created_at DESC,a.id DESC LIMIT 100",who,domain);}
 private static final String CURRENT_ROUTE="r.revoked_at IS NULL AND r.approved_by IS NOT NULL AND r.acknowledged_at IS NOT NULL AND r.expires_at>CURRENT_TIMESTAMP AND EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles role ON role.id=ur.role_id WHERE u.id=r.recipient_id AND u.status='ACTIVE' AND u.email_verified AND u.deleted_at IS NULL AND role.name='TRUST_'||CASE r.domain WHEN 'GROUP' THEN 'SOCIAL' ELSE r.domain END) AND EXISTS(SELECT 1 FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles role ON role.id=ur.role_id WHERE u.id=r.approved_by AND u.status='ACTIVE' AND u.email_verified AND role.name='TRUST_PLATFORM' AND EXISTS(SELECT 1 FROM user_roles domain_role JOIN roles dr ON dr.id=domain_role.role_id WHERE domain_role.user_id=u.id AND dr.name='TRUST_'||CASE r.domain WHEN 'GROUP' THEN 'SOCIAL' ELSE r.domain END))";
 @Scheduled(fixedDelayString="${greenocean.operations.alert-sweep-ms:5000}",initialDelayString="${greenocean.operations.alert-sweep-ms:5000}") public void sweep(){if(enabled&&dispatching.compareAndSet(false,true))try{dispatch.execute(()->{try{drain();}finally{dispatching.set(false);}});}catch(java.util.concurrent.RejectedExecutionException stopped){dispatching.set(false);}}
 @jakarta.annotation.PreDestroy public void close(){dispatch.shutdownNow();try{dispatch.awaitTermination(5,java.util.concurrent.TimeUnit.SECONDS);}catch(InterruptedException interrupted){Thread.currentThread().interrupt();}}
 public void drain(){if(!enabled)return;
  tx.executeWithoutResult(status->{db.update("INSERT INTO operation_alerts(incident_id,route_id) SELECT i.id,r.id FROM operation_incidents i JOIN operation_alert_routes r ON r.domain=i.domain WHERE i.state NOT IN('RESOLVED','POST_INCIDENT_REVIEW','CLOSED') AND "+CURRENT_ROUTE+" AND(r.escalation_level=0 OR(i.created_at<CURRENT_TIMESTAMP-(?*INTERVAL '1 second') AND NOT EXISTS(SELECT 1 FROM operation_alerts a WHERE a.incident_id=i.id AND a.acknowledged_at IS NOT NULL))) ON CONFLICT DO NOTHING",escalationSeconds);});
  for(int n=0;n<10;n++){Map<String,Object> job=tx.execute(status->{if(!Boolean.TRUE.equals(db.queryForObject("SELECT pg_try_advisory_xact_lock(hashtextextended('operation-alert-global-budget',0))",Boolean.class)))return null;if(db.queryForObject("SELECT count(*) FROM audit_logs WHERE action='OPERATION_ALERT_DISPATCH' AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 minute'",Integer.class)>=60)return null;var rows=db.queryForList("SELECT a.id,a.incident_id,a.route_id,r.destination_key,i.domain,i.kind,i.severity,i.state AS incident_state FROM operation_alerts a JOIN operation_alert_routes r ON r.id=a.route_id JOIN operation_incidents i ON i.id=a.incident_id WHERE(a.state='QUEUED' OR(a.state='CLAIMED' AND a.claimed_at<CURRENT_TIMESTAMP-INTERVAL '30 seconds')) AND a.next_attempt_at<=CURRENT_TIMESTAMP AND a.attempts<5 AND "+CURRENT_ROUTE+" ORDER BY a.created_at,a.id LIMIT 1 FOR UPDATE OF a SKIP LOCKED");if(rows.isEmpty())return null;var r=rows.getFirst();UUID claim=UUID.randomUUID();db.update("UPDATE operation_alerts SET state='CLAIMED',claim_id=?,claimed_at=CURRENT_TIMESTAMP,attempts=attempts+1 WHERE id=?",claim,r.get("id"));db.update("INSERT INTO audit_logs(action,entity_type,entity_id) VALUES('OPERATION_ALERT_DISPATCH','OPERATION_ALERT',?)",r.get("id"));r.put("claim",claim);return r;});if(job==null)break;
   String payload=json.writeValueAsString(Map.of("deliveryId",job.get("id"),"incidentId",job.get("incident_id"),"domain",job.get("domain"),"kind",job.get("kind"),"severity",job.get("severity"),"state",job.get("incident_state"),"humanAcknowledgement",false));int result=gateway.send((String)job.get("destination_key"),(UUID)job.get("id"),payload);
   tx.executeWithoutResult(status->{boolean delivered=result>=200&&result<300;db.update("UPDATE operation_alerts SET state=CASE WHEN ? THEN 'DELIVERED' WHEN attempts>=5 THEN 'FAILED' ELSE 'QUEUED' END,delivered_at=CASE WHEN ? THEN CURRENT_TIMESTAMP ELSE NULL END,last_status=?,next_attempt_at=CURRENT_TIMESTAMP+(LEAST(300,5*power(2,attempts)) *INTERVAL '1 second'),claim_id=NULL WHERE id=? AND claim_id=? AND state='CLAIMED'",delivered,delivered,result==0?null:result,job.get("id"),job.get("claim"));});
  }
 }
}
